package com.fitbite.service;
import com.fitbite.dto.*; import com.fitbite.dto.RecipeDtos.*; import com.fitbite.entity.*; import com.fitbite.exception.ResourceNotFoundException; import com.fitbite.repository.*; import org.springframework.cache.annotation.*; import org.springframework.data.domain.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.Instant; import java.util.*;
@Service public class RecipeService { private final RecipeRepository recipes; private final CategoryRepository categories; private final IngredientRepository ingredients; private final HealthGoalRepository goals; private final CurrentUserService current; private final RecipeHistoryRepository history;
 public RecipeService(RecipeRepository recipes,CategoryRepository categories,IngredientRepository ingredients,HealthGoalRepository goals,CurrentUserService current,RecipeHistoryRepository history){this.recipes=recipes;this.categories=categories;this.ingredients=ingredients;this.goals=goals;this.current=current;this.history=history;}
 @Transactional(readOnly=true) public RecipeDetail get(Long id){Recipe r=recipes.findById(id).orElseThrow(()->new ResourceNotFoundException("Recipe not found")); boolean fav=false; try{fav=current.get().getFavorites().contains(r);}catch(Exception ignored){} return RecipeMapper.detail(r,fav);}
 @Transactional public Page<RecipeSummary> search(String q,String meal,String cuisine,String diet,String health,Double maxCalories,Double minProtein,Integer maxTime,String difficulty,int page,int size,String sort){String safeSort=safeSort(sort); Pageable p=PageRequest.of(Math.max(0,page),Math.min(50,Math.max(1,size)),Sort.by(safeSort.startsWith("-")?Sort.Direction.DESC:Sort.Direction.ASC,safeSort.replaceFirst("^-",""))); Page<Recipe> result=recipes.search(nullToEmpty(q),nullToEmpty(meal),nullToEmpty(cuisine),nullToEmpty(diet),nullToEmpty(health),maxCalories,minProtein,maxTime,nullToEmpty(difficulty),p); boolean auth=isAuth(); Set<Recipe> favs=auth?current.get().getFavorites():Set.of(); return result.map(r->RecipeMapper.summary(r,favs.contains(r)));}
 private boolean isAuth(){var a=org.springframework.security.core.context.SecurityContextHolder.getContext().getAuthentication();return a!=null&&a.isAuthenticated()&&!a.getName().equals("anonymousUser");}
 @Transactional public RecipeDetail create(RecipeRequest req){return save(null,req);} @Transactional @CacheEvict(cacheNames="recipes",allEntries=true) public RecipeDetail update(Long id,RecipeRequest req){return save(id,req);} @Transactional @CacheEvict(cacheNames="recipes",allEntries=true) public void delete(Long id){if(!recipes.existsById(id))throw new ResourceNotFoundException("Recipe not found");recipes.deleteById(id);}
 private RecipeDetail save(Long id,RecipeRequest req){Recipe r=id==null?new Recipe():recipes.findById(id).orElseThrow(()->new ResourceNotFoundException("Recipe not found"));Category c=categories.findByNameIgnoreCase(req.category()).orElseGet(()->categories.save(Category.builder().name(req.category()).build()));r.setName(req.name());r.setDescription(req.description());r.setCategory(c);r.setCuisine(req.cuisine());r.setMealType(req.mealType());r.getIngredients().clear();for(var in:req.ingredients()){Ingredient ing=ingredients.findByNameIgnoreCase(in.name()).orElseGet(()->ingredients.save(Ingredient.builder().name(in.name()).unit("unit").build()));r.addIngredient(ing,in.quantity());}r.setSteps(req.steps());r.setPreparationTime(req.preparationTime());r.setCookingTime(req.cookingTime());r.setTotalTime(req.preparationTime()+req.cookingTime());r.setServings(req.servings());r.setCalories(req.calories());r.setProtein(req.protein());r.setCarbohydrates(req.carbohydrates());r.setFat(req.fat());r.setFiber(req.fiber());r.setSodium(req.sodium());r.setDifficulty(req.difficulty());r.setDietaryTags(req.dietaryTags());r.setHealthTags(req.healthTags());r.setImageUrl(req.imageUrl());r.setNutritionSource(req.nutritionSource());r.setUpdatedAt(Instant.now());r.getHealthGoals().clear();if(req.healthGoals()!=null)for(String g:req.healthGoals())goals.findByNameIgnoreCase(g).ifPresent(r.getHealthGoals()::add);return RecipeMapper.detail(recipes.save(r),false);}
 @Transactional public void recordView(Long id){Recipe r=recipes.findById(id).orElseThrow(()->new ResourceNotFoundException("Recipe not found"));history.save(RecipeHistory.builder().user(current.get()).recipe(r).build());}
 public List<RecipeSummary> recent(){Set<Recipe> fav=current.get().getFavorites();return history.findTop10ByUserIdOrderByViewedAtDesc(current.get().getId()).stream().map(h->RecipeMapper.summary(h.getRecipe(),fav.contains(h.getRecipe()))).toList();}
 private static String nullToEmpty(String x){return x==null?"":x;} private static String safeSort(String sort){String s=nullToEmpty(sort);String field=s.startsWith("-")?s.substring(1):s;Set<String> allowed=Set.of("name","calories","protein","totalTime","createdAt");return allowed.contains(field)?s:"name";}
}
